private _showDataInfo(isEmphasis?: boolean) {
    // Always show when drgging.
    isEmphasis = this._dragging || isEmphasis;
    const displayables = this._displayables;
    const handleLabels = displayables.handleLabels;

    const dataZoomModel = this.dataZoomModel;
    const normalShow = dataZoomModel.get(['handleLabel', 'show']) || false;
    const emphasisShow = dataZoomModel.get(['emphasis', 'handleLabel', 'show']) || false;
    const toShow = isEmphasis ? emphasisShow : normalShow;

    handleLabels[0].attr('invisible', !toShow);
    handleLabels[1].attr('invisible', !toShow);

    // Highlight move handle
    displayables.moveHandle
        && this.api[isEmphasis ? 'enterEmphasis' : 'leaveEmphasis'](displayables.moveHandle, 1);
