import { createChart, getGraphicElements } from '../../../core/utHelper';
import { EChartsType } from '../../../../../src/echarts';
import { SliderDataZoomOption } from '../../../../../src/component/dataZoom/SliderZoomModel';
import Element from 'zrender/src/Element';

function makeOption(dataZoomOption: SliderDataZoomOption) {
    return {
        xAxis: {
            type: 'category' as const,
            data: ['A', 'B', 'C', 'D', 'E']
        },
        yAxis: {},
        dataZoom: [dataZoomOption],
        series: [{
            type: 'line' as const,
            data: [1, 2, 3, 4, 5]
        }]
    };
}

function getHandleLabels(chart: EChartsType): Element[] {
    return getGraphicElements(chart, 'dataZoom', 0).filter(function (el) {
        return el.type === 'text';
    });
}

function getInvisibles(chart: EChartsType): boolean[] {
    return getHandleLabels(chart).map(function (el) {
        return !!el.invisible;
    });
}

describe('dataZoom/handleLabel', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        chart.dispose();
    });

    it('should hide handle labels in normal state by default', function () {
        chart.setOption(makeOption({ type: 'slider' }));

        const labels = getHandleLabels(chart);
        expect(labels.length).toBe(2);
        expect(getInvisibles(chart)).toEqual([true, true]);
    });

    it('should show handle labels in normal state when handleLabel.show is true', function () {
        chart.setOption(makeOption({
            type: 'slider',
            handleLabel: {
                show: true
            }
        }));

        expect(getInvisibles(chart)).toEqual([false, false]);
    });

    it('should show handle labels on emphasis by default and restore on normal', function () {
        chart.setOption(makeOption({ type: 'slider' }));

        const view = (chart as any)._componentsViews.filter(function (v: any) {
            return v.type === 'dataZoom.slider';
        })[0];

        view._showDataInfo(true);
        expect(getInvisibles(chart)).toEqual([false, false]);

        view._showDataInfo(false);
        expect(getInvisibles(chart)).toEqual([true, true]);
    });

    it('emphasis.handleLabel.show should only control the emphasis state', function () {
        chart.setOption(makeOption({
            type: 'slider',
            handleLabel: {
                show: true
            },
            emphasis: {
                handleLabel: {
                    show: false
                }
            }
        }));

        const view = (chart as any)._componentsViews.filter(function (v: any) {
            return v.type === 'dataZoom.slider';
        })[0];

        // Normal state: visible.
        expect(getInvisibles(chart)).toEqual([false, false]);

        // Emphasis state: hidden because emphasis.handleLabel.show is false.
        view._showDataInfo(true);
        expect(getInvisibles(chart)).toEqual([true, true]);

        view._showDataInfo(false);
        expect(getInvisibles(chart)).toEqual([false, false]);
    });

});

