import { createChart } from '../../../core/utHelper';
import { EChartsType } from '../../../../../src/echarts';
import { SliderDataZoomOption } from '../../../../../src/component/dataZoom/SliderZoomModel';

function getSliderDisplayables(chart: EChartsType): any {
    const view = (chart as any)._componentsViews.filter(function (v: any) {
        return v.type === 'dataZoom.slider';
    })[0];
    return view._displayables;
}

function setSliderOption(chart: EChartsType, dataZoomOption: SliderDataZoomOption) {
    chart.setOption({
        xAxis: {
            type: 'category',
            data: ['A', 'B', 'C', 'D', 'E']
        },
        yAxis: {},
        dataZoom: [dataZoomOption],
        series: [{
            type: 'line',
            data: [1, 2, 3, 4, 5]
        }]
    });
}

describe('dataZoom/moveHandleCursor', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        chart.dispose();
    });

    it('move zone should use the default cursor but stay draggable', function () {
        setSliderOption(chart, { type: 'slider' });

        const displayables = getSliderDisplayables(chart);
        expect(displayables.moveZone).toBeTruthy();
        expect(displayables.moveZone.cursor).toBe('default');
        expect(displayables.moveZone.draggable).toBe(true);
    });

    it('move zone should use the default cursor when brushSelect is disabled', function () {
        setSliderOption(chart, { type: 'slider', brushSelect: false });

        const displayables = getSliderDisplayables(chart);
        // Without brushSelect the filler itself is the move zone.
        expect(displayables.moveZone).toBeFalsy();
        expect(displayables.filler.cursor).toBe('default');
        expect(displayables.filler.draggable).toBe(true);
    });

    it('resize handles cursors should not regress', function () {
        setSliderOption(chart, { type: 'slider' });

        const handles = getSliderDisplayables(chart).handles;
        expect(handles[0].cursor).toBe('ew-resize');
        expect(handles[1].cursor).toBe('ew-resize');
    });

    it('vertical resize handles should keep ns-resize', function () {
        chart.setOption({
            xAxis: {},
            yAxis: {
                type: 'category',
                data: ['A', 'B', 'C', 'D', 'E']
            },
            dataZoom: [{
                type: 'slider',
                orient: 'vertical',
                yAxisIndex: 0
            }],
            series: [{
                type: 'line',
                data: [1, 2, 3, 4, 5]
            }]
        });

        const displayables = getSliderDisplayables(chart);
        expect(displayables.handles[0].cursor).toBe('ns-resize');
        expect(displayables.handles[1].cursor).toBe('ns-resize');
        expect(displayables.moveZone.cursor).toBe('default');
    });

});
